declare const tools: { mcp__meshy_mcp_server__meshy_multi_image_to_3d(args: {
  // 'latest' (default, = Meshy 7.1) or 'meshy-7.1' (best), 'meshy-6', 'meshy-6-lite' (fast, cheap, 2K textures only); 'meshy-7' is deprecated. No Smart Topology here.
  ai_model?: "meshy-6-lite" | "meshy-6" | "meshy-7" | "meshy-7.1" | "latest";
  // Also return a transparent-background preview (alpha_thumbnail_url).
  alpha_thumbnail?: boolean;
  // AI-estimate the real-world height and resize to it (default false).
  auto_size?: boolean;
  // Adaptive decimation 1 (ultra) – 4 (low); overrides target_polycount.
  decimation_mode?: number;
  // Also make metallic/roughness/normal maps. Not with texture_model meshy-n1.
  enable_pbr?: boolean;
  // 1–4 absolute paths to local .jpg/.jpeg/.png/.webp images; the server encodes them.
  file_paths?: Array<string>;
  // Ultra geometry pass: standard (default) or 2k (+5 credits); meshy-7.1/latest only. No 4k here.
  geometry_resolution?: "standard" | "2k";
  // Deprecated: use texture_resolution '4k'.
  hd_texture?: boolean;
  // Optimize the input image (meshy-6/7.1/latest); false keeps deliberate styling.
  image_enhancement?: boolean;
  // 1–4 public image URLs.
  image_urls?: Array<string>;
  // A SUCCEEDED text-to-image / image-to-image task (multi-view included) whose images are the input.
  input_task_id?: string;
  // Deprecated; ignored (this endpoint has no model_type).
  model_type?: "standard" | "lowpoly";
  // Also return front/back/left/right thumbnails.
  multi_view_thumbnails?: boolean;
  // 'bottom' or 'center' (default bottom with auto_size).
  origin_at?: "bottom" | "center";
  // 'a-pose' or 't-pose'; use 't-pose' when the model will be rigged or animated.
  pose_mode?: "a-pose" | "t-pose";
  // Remove highlights/shadows from the base color (meshy-6/7.1/latest; API default true). Not true with texture_model meshy-n1.
  remove_lighting?: boolean;
  // markdown (default) or json
  response_format?: "markdown" | "json";
  // Also keep the GLB from before remeshing (with should_remesh).
  save_pre_remeshed_model?: boolean;
  // Remesh to target_polycount / topology (default false).
  should_remesh?: boolean;
  // Generate textures (default true); false gives a cheaper untextured mesh.
  should_texture?: boolean;
  // Deprecated: has no effect.
  symmetry_mode?: "off" | "auto" | "on";
  // Formats to produce (default: all but 3mf; list '3mf' to get it). Fewer formats finish faster.
  target_formats?: Array<"glb" | "obj" | "fbx" | "stl" | "usdz" | "3mf">;
  // Remesh target 100–300,000, needs should_remesh true.
  target_polycount?: number;
  // Image URL to guide texturing. Not with texture_prompt. With texture_model meshy-n1, the front view it textures from.
  texture_image_url?: string;
  // 1–4 views (URLs or data URIs) of the SAME object to drive the texture; element 0 is the front. ai_model meshy-7.1/latest, or texture_model meshy-7 / meshy-n1; not with texture_prompt / texture_image_url.
  texture_image_urls?: Array<string>;
  // Texture model, picked apart from the geometry: meshy-7 (PBR, 2K/4K/8K) or meshy-n1 (2K base color from texture_image_urls / texture_image_url, else the input images, first = front; no texture_prompt, enable_pbr, 4k/8k, remove_lighting or quad remesh). Either also allows texture_image_urls on meshy-6 / meshy-6-lite. No meshy-6-lite here. Omit for the geometry's default: meshy-7 (meshy-7.1, latest, meshy-t2, meshy-t2.5), meshy-6 (meshy-6), meshy-6-lite (meshy-6-lite). Same price whichever; ignored with should_texture false.
  texture_model?: "meshy-7" | "meshy-n1";
  // Text to guide texturing (max 800 characters). Not with texture_image_url. Not with texture_model meshy-n1.
  texture_prompt?: string;
  // Base color texture: 2k (default), 4k or 8k (+5 credits; PBR maps stay 4K, no emission map). 4k/8k need the meshy-7 or meshy-6 texture model: not meshy-6-lite or meshy-n1.
  texture_resolution?: "2k" | "4k" | "8k";
  // quad or triangle (default).
  topology?: "quad" | "triangle";
  // Deprecated: use geometry_resolution '2k'.
  ultra_mode?: boolean;
}): Promise<CallToolResult<{ estimated_time: string; message: string; status: string; task_id: string; }>>; };
