declare const tools: { mcp__meshy_mcp_server__meshy_get_task_status(args: {
  // markdown (default) or json
  response_format?: "markdown" | "json";
  // Task ID
  task_id: string;
  // Optional: if omitted or wrong, the server finds the task and reports its real type.
  task_type?: "text-to-3d" | "image-to-3d" | "multi-image-to-3d" | "remesh" | "retexture" | "rigging" | "animation" | "text-to-image" | "image-to-image" | "convert" | "resize" | "uv-unwrap" | "multi-color-print" | "print-analyze" | "print-repair" | "print-split" | "text-to-motion" | "creative-lab-figure-prototype" | "creative-lab-figure-build" | "creative-lab-lamp-prototype" | "creative-lab-lamp-build" | "creative-lab-keychain-prototype" | "creative-lab-keychain-build" | "creative-lab-fridge-magnet-prototype" | "creative-lab-fridge-magnet-build" | "creative-lab-vinyl-figure-prototype" | "creative-lab-vinyl-figure-build" | "creative-lab-brick-figure-prototype" | "creative-lab-brick-figure-build" | "creative-lab-keycap-prototype" | "creative-lab-keycap-build" | "creative-lab-fidget-pixel-prototype" | "creative-lab-fidget-pixel-build" | "creative-lab-fidget-collapsible";
  // Max wait for this call when wait=true; the task keeps running after it.
  timeout_seconds?: number;
  // true (default): poll until it finishes; false: return the current status.
  wait?: boolean;
}): Promise<CallToolResult<{
  alpha_thumbnail_url?: string;
  // Credits consumed by the task (0 for FAILED — credits are refunded on failure)
  consumed_credits?: number;
  // e.g. image_too_complex
  error_code?: string;
  // Resolution guide for error_code
  error_doc_url?: string;
  error_message?: string;
  // Failure category if the task failed: invalid_input (fix the input), timeout / service_unavailable / server_error (refunded; create it again)
  error_type?: string;
  face_count?: number;
  image_urls?: Array<string>;
  model_urls?: { [key: string]: string; };
  // Outcome of this call; TIMEOUT means the wait ended, not the task
  outcome: "SUCCEEDED" | "FAILED" | "CANCELED" | "TIMEOUT" | "IN_PROGRESS" | "PENDING";
  // Auto Split: number of parts
  part_count?: number;
  poll_count?: number;
  // print-analyze result: status, issue counts, metrics, thin walls
  printability?: { [key: string]: unknown; };
  // 0–100
  progress: number;
  // Auto Split: the prompt was unreadable, so the cuts were chosen automatically
  prompt_ignored?: boolean;
  // Rigging, animation and text-to-motion file URLs
  result?: { [key: string]: unknown; };
  status: string;
  task_id: string;
  // The task's actual type (pass it as task_type to the download and cancel tools)
  task_type?: string;
  thumbnail_url?: string;
  vertex_count?: number;
  wait_time_seconds?: number;
}>>; };
